-- V0.9 Singapore Science: independent P3-P6 curriculum, vocabulary, practice and daily mastery
CREATE TABLE IF NOT EXISTS science_topics (
 id TEXT PRIMARY KEY, grade TEXT NOT NULL CHECK(grade IN ('P3','P4','P5','P6')), theme TEXT NOT NULL CHECK(theme IN ('Diversity','Cycles','Systems','Interactions','Energy')), title TEXT NOT NULL, summary TEXT NOT NULL, learning_points_json TEXT NOT NULL DEFAULT '[]', sort_order INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'published', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_science_topics_grade_theme ON science_topics(grade,theme,sort_order);
CREATE TABLE IF NOT EXISTS science_vocabulary (
 id TEXT PRIMARY KEY, topic_id TEXT NOT NULL REFERENCES science_topics(id) ON DELETE CASCADE, term TEXT NOT NULL, normalized_term TEXT NOT NULL, definition TEXT NOT NULL, example TEXT, sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(topic_id,normalized_term)
);
CREATE INDEX IF NOT EXISTS idx_science_vocab_topic ON science_vocabulary(topic_id,sort_order);
CREATE TABLE IF NOT EXISTS science_questions (
 id TEXT PRIMARY KEY, topic_id TEXT NOT NULL REFERENCES science_topics(id) ON DELETE CASCADE, question_type TEXT NOT NULL CHECK(question_type IN ('mcq','short_answer')), prompt TEXT NOT NULL, options_json TEXT, answer_json TEXT NOT NULL, explanation TEXT NOT NULL, difficulty INTEGER NOT NULL DEFAULT 1 CHECK(difficulty BETWEEN 1 AND 5), sort_order INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'published', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_science_questions_topic ON science_questions(topic_id,status,sort_order);
CREATE TABLE IF NOT EXISTS science_vocabulary_progress (
 child_id TEXT NOT NULL REFERENCES child_profiles(id) ON DELETE CASCADE, vocabulary_id TEXT NOT NULL REFERENCES science_vocabulary(id) ON DELETE CASCADE, mastery REAL NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, correct_count INTEGER NOT NULL DEFAULT 0, last_attempt_at TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(child_id,vocabulary_id)
);
CREATE TABLE IF NOT EXISTS science_question_attempts (
 id TEXT PRIMARY KEY, child_id TEXT NOT NULL REFERENCES child_profiles(id) ON DELETE CASCADE, question_id TEXT NOT NULL REFERENCES science_questions(id) ON DELETE CASCADE, correct INTEGER NOT NULL DEFAULT 0, response_json TEXT, score REAL NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_science_question_attempts_child_question ON science_question_attempts(child_id,question_id,created_at);
CREATE TABLE IF NOT EXISTS science_daily_settings (
 child_id TEXT PRIMARY KEY REFERENCES child_profiles(id) ON DELETE CASCADE, grade TEXT NOT NULL DEFAULT 'P5' CHECK(grade IN ('P3','P4','P5','P6')), theme TEXT, topic_id TEXT REFERENCES science_topics(id) ON DELETE SET NULL, vocabulary_target INTEGER NOT NULL DEFAULT 5, question_target INTEGER NOT NULL DEFAULT 5, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS science_daily_sessions (
 id TEXT PRIMARY KEY, child_id TEXT NOT NULL REFERENCES child_profiles(id) ON DELETE CASCADE, session_date TEXT NOT NULL, grade TEXT NOT NULL, theme TEXT, topic_id TEXT, total_items INTEGER NOT NULL DEFAULT 0, correct_items INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'in_progress' CHECK(status IN ('in_progress','completed')), started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_science_daily_sessions_child_date ON science_daily_sessions(child_id,session_date,status);
CREATE TABLE IF NOT EXISTS science_daily_session_items (
 id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES science_daily_sessions(id) ON DELETE CASCADE, item_type TEXT NOT NULL CHECK(item_type IN ('vocabulary','question')), item_id TEXT NOT NULL, item_order INTEGER NOT NULL, answered INTEGER NOT NULL DEFAULT 0, correct INTEGER, response_json TEXT, answered_at TEXT, UNIQUE(session_id,item_order)
);
CREATE INDEX IF NOT EXISTS idx_science_daily_items_session ON science_daily_session_items(session_id,item_order);
INSERT OR IGNORE INTO science_topics (id,grade,theme,title,summary,learning_points_json,sort_order) VALUES ('p3-diversity-living','P3','Diversity','Diversity of Living and Non-living Things','Identify characteristics of living things and classify organisms using observable features.','["Living things need resources, grow, respond to changes and reproduce.", "Non-living things do not carry out all the life processes of living things.", "Scientists classify living things by comparing observable similarities and differences.", "A classification rule must use a clear characteristic that can be observed."]',1);
