INSERT OR IGNORE INTO science_topics (id,grade,theme,title,summary,learning_points_json,sort_order) VALUES ('p3-life-cycles','P3','Cycles','Life Cycles of Plants and Animals','Recognise stages in life cycles and compare how different plants and animals develop.','["A life cycle shows the stages a living thing passes through as it grows and reproduces.", "Different animals can have different life-cycle stages.", "A seed can germinate and grow into a mature plant under suitable conditions.", "Adults reproduce so a new generation can begin its life cycle."]',3);
