INSERT OR IGNORE INTO science_questions (id,topic_id,question_type,prompt,options_json,answer_json,explanation,difficulty,sort_order) VALUES ('p6-environment-q01','p6-environment','mcq','Which meaning best matches “environment”?','["a sequence showing feeding relationships and energy transfer between organisms", "an organism, usually a green plant, that makes its own food", "the living and non-living surroundings that affect an organism", "all organisms of the same species living in an area"]','{"correctOption": 2, "answer": "the living and non-living surroundings that affect an organism"}','“environment” means the living and non-living surroundings that affect an organism.',1,1);
